#ifndef  _AVR_H
#define  _AVR_H

#include "avr_parms.H"
#include "systemc.h"
#include "ac_module.H"
#include "ac_utils.H"
#include "avr_arch.H"
#include "avr_isa.H"
#include "avr_syscall.H"


class avr: public ac_module, public avr_arch {
private:
  typedef struct {
    uint8_t op;
    uint8_t rd;
    uint8_t rr;
  } T_Type_2R;

  typedef struct {
    uint8_t op;
    uint8_t rd;
    uint8_t func;
  } T_Type_1R;

  typedef struct {
    uint8_t op;
    uint8_t k_hi;
    uint8_t rd_hi;
    uint8_t k_lo;
  } T_Type_Imm;

  typedef struct {
    uint8_t op;
    int8_t k_br;
    uint8_t cond;
  } T_Type_Branch;

  typedef struct {
    uint8_t op;
    int16_t k_jmp;
  } T_Type_RJMP;

  typedef struct {
    uint8_t op;
    uint8_t rd;
    uint8_t ptr;
  } T_Type_Ptr;

  typedef struct {
    uint8_t op;
    uint8_t pad;
  } T_Type_Halt;

  typedef struct {
    bool valid;
    void* end_rot;
    unsigned id;
    union {
      T_Type_2R F_Type_2R;
      T_Type_1R F_Type_1R;
      T_Type_Imm F_Type_Imm;
      T_Type_Branch F_Type_Branch;
      T_Type_RJMP F_Type_RJMP;
      T_Type_Ptr F_Type_Ptr;
      T_Type_Halt F_Type_Halt;
    };
  } DecCacheItem ;

public:

  bool has_delayed_load;
  char* delayed_load_program;
  avr_parms::avr_isa ISA;
  //!Address of Interpretation Routines.
  void** IntRoutine;

  DecCacheItem* DEC_CACHE;
  DecCacheItem* instr_dec;
  bool start_up;

  //!Dispatch Method.
  inline __attribute__((always_inline)) void* dispatch();

  //!Behavior execution method.
  void behavior();

  SC_HAS_PROCESS( avr );

  sc_event wake;

  //!Constructor.
  avr( sc_module_name name_ ): ac_module(name_), avr_arch(), ISA(*this) {
    SC_THREAD( behavior );
    sensitive << wake;
    has_delayed_load = false; 
    start_up=1;
    ac_id.write(globalId++);
  }

  void init_dec_cache() {
    DEC_CACHE = (DecCacheItem*) calloc(sizeof(DecCacheItem), (dec_cache_size / 2));
  }

  unsigned get_ac_pc();

  void set_ac_pc( unsigned int value );

  virtual void PrintStat();

  void init(int ac, char* av[]);

  void init();

  void set_prog_args();

  void load(char* program);

  void delayed_load(char* program);

  void stop(int status = 0);

  virtual ~avr() {};

};
#endif  //_AVR_H

